-- SYNTHETIC DEVELOPMENT ONLY. No Auth credentials are created. Never run against real school data.
-- Privileged fixture initialization only; ordinary-role RLS tests set their own full JWT claims afterward.
select set_config('request.jwt.claims','{"role":"service_role"}',false);
do $seed$ declare a jsonb;ver uuid;result_id uuid;p jsonb;question jsonb;begin
perform set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000003',true);
a:=public.start_attempt(jsonb_build_object('writer','40000000-0000-4000-8000-000000000999','versionId','40000000-0000-4000-8000-000000000700'));
perform public.save_answer(jsonb_build_object('attemptId',a->>'id','questionId','40000000-0000-4000-8000-000000000001','response','40000000-0000-4000-8000-000000000100','revision',1,'writer',a->>'writer'));
perform public.submit_attempt(jsonb_build_object('attemptId',a->>'id','writer',a->>'writer'));
perform set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
for question in select content from public.exam_questions where version_id='40000000-0000-4000-8000-000000000700' and type='subjective'loop perform public.review_grade(jsonb_build_object('attemptId',a->>'id','questionId',question->>'id','score',300,'revision',1,'feedback','Synthetic teacher feedback','reason','Synthetic fixture'));end loop;
result_id:=public.publish_result(jsonb_build_object('attemptId',a->>'id','reason','Synthetic result'));
